import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, SkipForward, SkipBack, Volume2, X, ChevronDown, Share2, Music } from 'lucide-react';
import Partager from './Partager';
import './Lecteur.css';

function Lecteur({ piste, playlist, onPisteChange, onFermer }) {
  const [enLecture, setEnLecture] = useState(false);
  const [progression, setProgression] = useState(0);
  const [duree, setDuree] = useState(0);
  const [volume, setVolume] = useState(1);
  const [pleinEcran, setPleinEcran] = useState(false);
  const [partagerOuvert, setPartagerOuvert] = useState(false);
  const audioRef = useRef(null);
  const estMonteRef = useRef(true);

  useEffect(() => {
    estMonteRef.current = true;
    return () => { estMonteRef.current = false; };
  }, []);

  useEffect(() => {
    if (!piste?.url) return;
    const ancienAudio = audioRef.current;
    if (ancienAudio) { ancienAudio.pause(); ancienAudio.src = ''; ancienAudio.load(); }

    const audio = new Audio();
    audioRef.current = audio;
    audio.volume = volume;
    setProgression(0);
    setDuree(0);
    setEnLecture(false);

    audio.addEventListener('loadedmetadata', () => { if (estMonteRef.current) setDuree(audio.duration); });
    audio.addEventListener('timeupdate', () => { if (estMonteRef.current) setProgression(audio.currentTime); });
    audio.addEventListener('ended', () => { if (estMonteRef.current) passerSuivante(); });
    audio.addEventListener('error', () => { if (estMonteRef.current) setEnLecture(false); });

    audio.src = piste.url;
    audio.load();
    const t = audio.play();
    if (t !== undefined) {
      t.then(() => { if (estMonteRef.current) setEnLecture(true); }).catch(() => {});
    }
    return () => { audio.pause(); audio.src = ''; };
  }, [piste?.url]);

  const passerSuivante = () => {
    if (!playlist?.length) return;
    const idx = playlist.findIndex(p => p.url === piste.url);
    onPisteChange(playlist[(idx + 1) % playlist.length]);
  };

  const passerPrecedente = () => {
    if (!playlist?.length) return;
    const idx = playlist.findIndex(p => p.url === piste.url);
    onPisteChange(playlist[(idx - 1 + playlist.length) % playlist.length]);
  };

  const toggleLecture = () => {
    if (!audioRef.current) return;
    if (enLecture) { audioRef.current.pause(); setEnLecture(false); }
    else {
      const p = audioRef.current.play();
      if (p !== undefined) p.then(() => setEnLecture(true)).catch(() => {});
    }
  };

  const handleProgression = (e) => {
    const val = parseFloat(e.target.value);
    if (audioRef.current) audioRef.current.currentTime = val;
    setProgression(val);
  };

  const handleVolume = (e) => {
    const val = parseFloat(e.target.value);
    if (audioRef.current) audioRef.current.volume = val;
    setVolume(val);
  };

  const formaterTemps = (s) => {
    if (!s || isNaN(s)) return '0:00';
    return `${Math.floor(s / 60)}:${Math.floor(s % 60).toString().padStart(2, '0')}`;
  };

  const pourcentage = duree > 0 ? (progression / duree) * 100 : 0;

  if (!piste) return null;

  // ═══════════════════════════════════════
  // MODE PLEIN ÉCRAN
  // ═══════════════════════════════════════
  if (pleinEcran) {
    return (
      <>
        <div className="lect-plein">
          {/* Fond flouté avec la pochette */}
          <div className="lect-plein-bg">
            {piste.pochette && <img src={piste.pochette} alt="" />}
          </div>

          {/* HEADER plein écran */}
          <div className="lect-plein-header">
            <button className="lect-plein-btn-retour" onClick={() => setPleinEcran(false)}>
              <ChevronDown size={26} />
            </button>
            <div className="lect-plein-header-titre">
              <span className="lect-plein-header-label">En lecture</span>
            </div>
            <button className="lect-plein-btn-partager" onClick={() => setPartagerOuvert(true)}>
              <Share2 size={20} />
            </button>
          </div>

          {/* GRANDE POCHETTE */}
          <div className="lect-plein-pochette-wrapper">
            {piste.pochette
              ? <img src={piste.pochette} alt={piste.titre} className="lect-plein-pochette" />
              : <div className="lect-plein-pochette-vide"><Music size={80} /></div>
            }
          </div>

          {/* TITRE + ARTISTE centrés */}
          <div className="lect-plein-infos">
            <h2 className="lect-plein-titre">{piste.titre}</h2>
            <p className="lect-plein-artiste">{piste.artiste}</p>
          </div>

          {/* BARRE DE PROGRESSION */}
          <div className="lect-plein-progression">
            <div className="lect-plein-barre-wrapper">
              <div className="lect-plein-barre-bg">
                <div className="lect-plein-barre-remplie" style={{ width: `${pourcentage}%` }} />
                <input type="range" min="0" max={duree || 0} value={progression} onChange={handleProgression} className="lect-plein-barre-input" />
              </div>
            </div>
            <div className="lect-plein-temps">
              <span>{formaterTemps(progression)}</span>
              <span>{formaterTemps(duree)}</span>
            </div>
          </div>

          {/* CONTRÔLES */}
          <div className="lect-plein-controles">
            <button className="lect-plein-btn-nav" onClick={passerPrecedente}>
              <SkipBack size={28} />
            </button>
            <button className="lect-plein-btn-play" onClick={toggleLecture}>
              {enLecture ? <Pause size={32} /> : <Play size={32} />}
            </button>
            <button className="lect-plein-btn-nav" onClick={passerSuivante}>
              <SkipForward size={28} />
            </button>
          </div>

          {/* VOLUME */}
          <div className="lect-plein-volume">
            <Volume2 size={14} />
            <input type="range" min="0" max="1" step="0.01" value={volume} onChange={handleVolume} className="lect-plein-volume-input" />
          </div>
        </div>

        {partagerOuvert && (
          <Partager
            lien={`${window.location.origin}?single=${piste.id}`}
            titre={`${piste.titre}${piste.artiste ? ' — ' + piste.artiste : ''}`}
            onFermer={() => setPartagerOuvert(false)}
          />
        )}
      </>
    );
  }

  // ═══════════════════════════════════════
  // MODE MINI (barre du bas)
  // ═══════════════════════════════════════
  return (
    <div className="lecteur-global" onClick={() => setPleinEcran(true)}>
      {/* Barre de progression fine tout en haut du lecteur mini */}
      <div className="lect-mini-progress-bar">
        <div className="lect-mini-progress-remplie" style={{ width: `${pourcentage}%` }} />
      </div>

      <div className="lecteur-gauche">
        {piste.pochette
          ? <img src={piste.pochette} alt={piste.titre} className="lecteur-pochette" />
          : <div className="lecteur-pochette-defaut"><Music size={18} /></div>
        }
        <div className="lecteur-info">
          <span className="lecteur-titre">{piste.titre}</span>
          <span className="lecteur-artiste">{piste.artiste}</span>
        </div>
      </div>

      <div className="lect-mini-droite" onClick={e => e.stopPropagation()}>
        <button className="lecteur-btn" onClick={toggleLecture}>
          {enLecture ? <Pause size={22} /> : <Play size={22} />}
        </button>
        <button className="lecteur-btn-fermer" onClick={() => { audioRef.current?.pause(); onFermer(); }}>
          <X size={20} />
        </button>
      </div>
    </div>
  );
}

export default Lecteur;
